-- HaechiVN local demo data (generated). Safe to re-run: rows are upserted by id.
DELETE FROM study_sessions WHERE id LIKE 'ss_%';
DELETE FROM checkins WHERE id LIKE 'ck_%';
DELETE FROM card_states WHERE id LIKE 'cs_%';
DELETE FROM achievements WHERE id LIKE 'ach_%';
DELETE FROM community_posts WHERE id LIKE 'post_demo_%';
DELETE FROM daily_mission_claims WHERE id LIKE 'dm_%';
DELETE FROM assignment_progress WHERE assignment_id LIKE 'as_demo_%';
DELETE FROM class_assignments WHERE id LIKE 'as_demo_%';
-- Login demo: hocvien@test.local / demo1234 (student), admin@test.local / admin (admin, local only).
PRAGMA foreign_keys = ON;

