INSERT OR REPLACE INTO community_posts (id, user_id, category, title, body, status, created_at) VALUES
  ('post_demo_1', 'u_demo_01', 'study', 'Cách mình giữ chuỗi 35 ngày khi bận', 'Mỗi tối mình chỉ học 15 phút nhưng luôn mở app trước khi ngủ. Quan trọng là không đứt chuỗi, hôm nào mệt thì ôn 5 thẻ thôi.', 'published', '2026-11-13 14:20:00'),
  ('post_demo_2', 'u_demo_03', 'question', 'Shadowing nên chọn bài nào ở trình độ sơ cấp?', 'Mình mới hết Sơ cấp 1, đang phân vân giữa shadowing hội thoại ngắn và shadowing tin tức. Mọi người thấy cái nào dễ vào hơn?', 'published', '2026-11-12 09:20:00'),
  ('post_demo_3', 'u_demo_05', 'resource', 'Bộ 60 câu TOPIK II mình tự soạn', 'Mình tổng hợp 60 câu đọc hiểu hay gặp trong đề TOPIK II, chia theo dạng câu hỏi. Ai cần mình chia sẻ lại trong phần bình luận nhé.', 'published', '2026-11-11 19:20:00'),
  ('post_demo_4', 'u_demo_07', 'conversation', 'Tuần này mọi người đang học chủ đề gì?', 'Mình đang học từ vựng về du lịch và nhà hàng. Ai có mẹo nhớ từ lâu thì chỉ mình với!', 'published', '2026-11-10 12:20:00'),
  ('post_demo_5', 'u_demo_02', 'study', 'Đổi giờ học từ tối sang sáng hiệu quả hơn hẳn', 'Trước mình học 23h nên hay buồn ngủ. Chuyển sang 6h sáng, mỗi ngày 25 phút, được 12 ngày liên tục rồi.', 'published', '2026-11-09 06:20:00'),
  ('post_demo_6', 'u_demo_09', 'question', 'Dictation sai hoài từ đồng âm thì sửa sao?', 'Mình hay nhầm các từ có patchim khi nghe. Có cách luyện nào giúp phân biệt rõ hơn không ạ?', 'published', '2026-11-08 15:20:00');

